import { describe, expect, it } from "vitest";
import {
  DISCLAIMER_BADGE_TEXT,
  DISCLAIMER_TEXT,
  DISCLAIMER_TITLE,
  withDisclaimerMarkdown,
} from "./disclaimer";

describe("disclaimer copy", () => {
  it("matches the contract wording exactly", () => {
    expect(DISCLAIMER_TITLE).toBe("AI-generated analysis: human review required");
    expect(DISCLAIMER_TEXT).toBe(
      "This output was generated by AI and can be wrong. A qualified human analyst must review it before any action is taken.",
    );
    expect(DISCLAIMER_BADGE_TEXT).toBe("AI OUTPUT: HUMAN REVIEW REQUIRED");
  });

  it("uses no em or en dashes", () => {
    for (const s of [DISCLAIMER_TITLE, DISCLAIMER_TEXT, DISCLAIMER_BADGE_TEXT]) {
      expect(s).not.toMatch(/[\u2013\u2014]/);
    }
  });
});

describe("withDisclaimerMarkdown", () => {
  const line = `**${DISCLAIMER_TITLE}.** ${DISCLAIMER_TEXT}`;

  it("puts the bold disclaimer at the top and the bottom", () => {
    const out = withDisclaimerMarkdown("## Verdict\nPhishing");
    expect(out.startsWith(line)).toBe(true);
    expect(out.endsWith(line)).toBe(true);
    expect(out).toContain("## Verdict\nPhishing");
  });

  it("is idempotent when the report already carries both ends", () => {
    const once = withDisclaimerMarkdown("body");
    expect(withDisclaimerMarkdown(once)).toBe(once);
    expect(once.split(DISCLAIMER_TEXT).length - 1).toBe(2);
  });

  it("adds only the missing end", () => {
    const footerOnly = `body\n\n---\n\n${line}`;
    const fixed = withDisclaimerMarkdown(footerOnly);
    expect(fixed.startsWith(line) && fixed.endsWith(line)).toBe(true);
    expect(fixed.split(DISCLAIMER_TEXT).length - 1).toBe(2);
    const headerOnly = `${line}\n\n---\n\nbody`;
    const fixed2 = withDisclaimerMarkdown(headerOnly);
    expect(fixed2.split(DISCLAIMER_TEXT).length - 1).toBe(2);
  });
});
